395→    #[test]
396→    fn scrub_removes_sk_tokens() {
397→        let input = "key: sk-abcdefghij1234567890abcdef";
398→        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
399→        assert!(scrubbed.contains("[REDACTED]"));
400→        assert!(!scrubbed.contains("sk-"));
401→    }
402→
403→    #[test]
404→    fn scrub_removes_home_paths() {
405→        let input = "Error at /home/user/project/file.rs:42";
406→        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
407→        assert!(scrubbed.contains("[PATH]"));
408→        assert!(!scrubbed.contains("/home/user"));
409→    }
410→}
