  1→//! Output masking for secret values.
  2→//!
  3→//! This module provides functionality for masking sensitive values in output streams.
  4→
  5→use std::collections::HashMap;
  6→use std::io::{self, Write};
  7→
  8→/// Masks secret values in output streams.
  9→///
 10→/// # Example
 11→///
 12→/// ```
 13→/// use bivvy::secrets::OutputMasker;
 14→///
 15→/// let mut masker = OutputMasker::new();
 16→/// masker.add_secret("super-secret-value");
 17→///
 18→/// let output = masker.mask("The key is super-secret-value here");
 19→/// assert_eq!(output, "The key is [REDACTED] here");
 20→/// assert!(!output.contains("super-secret-value"));
 21→/// ```
 22→pub struct OutputMasker {
 23→    /// Map of secret values to their masked representation.
 24→    secrets: HashMap<String, String>,
 25→    /// The mask string to use.
 26→    mask: String,
 27→}
 28→
 29→impl OutputMasker {
 30→    /// Create a new masker with default mask string.
 31→    pub fn new() -> Self {
 32→        Self {
 33→            secrets: HashMap::new(),
 34→            mask: "[REDACTED]".to_string(),
 35→        }
 36→    }
 37→
 38→    /// Create a masker with a custom mask string.
 39→    ///
 40→    /// # Example
 41→    ///
 42→    /// ```
 43→    /// use bivvy::secrets::OutputMasker;
 44→    ///
 45→    /// let mut masker = OutputMasker::with_mask("***");
 46→    /// masker.add_secret("password123");
 47→    ///
 48→    /// let output = masker.mask("password: password123");
 49→    /// assert_eq!(output, "password: ***");
 50→    /// ```
 51→    pub fn with_mask(mask: impl Into<String>) -> Self {
 52→        Self {
 53→            secrets: HashMap::new(),
 54→            mask: mask.into(),
 55→        }
 56→    }
 57→
 58→    /// Register a secret value to be masked.
 59→    ///
 60→    /// Empty strings are ignored.
 61→    pub fn add_secret(&mut self, value: impl Into<String>) {
 62→        let value = value.into();
 63→        if !value.is_empty() {
 64→            self.secrets.insert(value, self.mask.clone());
 65→        }
 66→    }
 67→
 68→    /// Register multiple secret values.
 69→    pub fn add_secrets(&mut self, values: impl IntoIterator<Item = impl Into<String>>) {
 70→        for value in values {
 71→            self.add_secret(value);
 72→        }
 73→    }
 74→
 75→    /// Mask any secret values in the given string.
 76→    pub fn mask(&self, input: &str) -> String {
 77→        let mut result = input.to_string();
 78→        for (secret, mask) in &self.secrets {
 79→            result = result.replace(secret, mask);
 80→        }
 81→        result
 82→    }
 83→
 84→    /// Get the number of registered secrets.
 85→    pub fn secret_count(&self) -> usize {
 86→        self.secrets.len()
 87→    }
 88→
 89→    /// Create a writer that masks output.
 90→    ///
 91→    /// # Example
 92→    ///
 93→    /// ```
 94→    /// use bivvy::secrets::OutputMasker;
 95→    /// use std::io::Write;
 96→    ///
 97→    /// let mut masker = OutputMasker::new();
 98→    /// masker.add_secret("secret-value");
 99→    ///
100→    /// let mut output = Vec::new();

  1→//! Secret pattern matching.
  2→//!
  3→//! This module provides functionality for detecting secret environment variables
  4→//! by matching their names against patterns.
  5→
  6→use regex::Regex;
  7→
  8→/// A pattern that identifies secret values.
  9→#[derive(Debug, Clone)]
 10→pub struct SecretPattern {
 11→    /// Name of this pattern (for debugging).
 12→    pub name: String,
 13→    /// Regex pattern to match environment variable names.
 14→    pub env_pattern: Regex,
 15→}
 16→
 17→/// Built-in patterns for common secrets.
 18→///
 19→/// Each tuple contains (name, regex_pattern).
 20→pub const BUILTIN_PATTERNS: &[(&str, &str)] = &[
 21→    ("api_key", r"(?i)^.*_?(API_?KEY|APIKEY)$"),
 22→    ("secret", r"(?i)^.*_?(SECRET|SECRET_KEY)$"),
 23→    ("token", r"(?i)^.*_?(TOKEN|ACCESS_TOKEN|AUTH_TOKEN)$"),
 24→    ("password", r"(?i)^.*_?(PASSWORD|PASSWD|PWD)$"),
 25→    ("credential", r"(?i)^.*_?CREDENTIAL$"),
 26→    ("private_key", r"(?i)^.*_?PRIVATE_KEY$"),
 27→    (
 28→        "connection_string",
 29→        r"(?i)^.*(CONNECTION_STRING|DATABASE_URL)$",
 30→    ),
 31→];
 32→
 33→/// Matches environment variable names against secret patterns.
 34→///
 35→/// # Example
 36→///
 37→/// ```
 38→/// use bivvy::secrets::SecretMatcher;
 39→///
 40→/// let matcher = SecretMatcher::with_builtins();
 41→///
 42→/// // Common secret patterns are detected
 43→/// assert!(matcher.is_secret("API_KEY"));
 44→/// assert!(matcher.is_secret("GITHUB_TOKEN"));
 45→/// assert!(matcher.is_secret("DB_PASSWORD"));
 46→///
 47→/// // Non-secrets are not flagged
 48→/// assert!(!matcher.is_secret("PATH"));
 49→/// assert!(!matcher.is_secret("HOME"));
 50→/// ```
 51→pub struct SecretMatcher {
 52→    patterns: Vec<SecretPattern>,
 53→}
 54→
 55→impl SecretMatcher {
 56→    /// Create a matcher with built-in patterns.
 57→    pub fn with_builtins() -> Self {
 58→        let patterns = BUILTIN_PATTERNS
 59→            .iter()
 60→            .map(|(name, pattern)| SecretPattern {
 61→                name: name.to_string(),
 62→                env_pattern: Regex::new(pattern).unwrap(),
 63→            })
 64→            .collect();
 65→
 66→        Self { patterns }
 67→    }
 68→
 69→    /// Create a matcher with custom patterns.
 70→    pub fn new(patterns: Vec<SecretPattern>) -> Self {
 71→        Self { patterns }
 72→    }
 73→
 74→    /// Create a matcher with built-in patterns plus custom exact matches.
 75→    ///
 76→    /// # Example
 77→    ///
 78→    /// ```
 79→    /// use bivvy::secrets::SecretMatcher;
 80→    ///
 81→    /// let custom = vec!["MY_CUSTOM_SECRET".to_string()];
 82→    /// let matcher = SecretMatcher::with_builtins_and_custom(&custom);
 83→    ///
 84→    /// // Custom patterns are detected
 85→    /// assert!(matcher.is_secret("MY_CUSTOM_SECRET"));
 86→    /// // Built-ins still work
 87→    /// assert!(matcher.is_secret("API_KEY"));
 88→    /// ```
 89→    pub fn with_builtins_and_custom(custom_names: &[String]) -> Self {
 90→        let mut matcher = Self::with_builtins();
 91→
 92→        for name in custom_names {
 93→            // Add exact match pattern for each custom name
 94→            if let Ok(pattern) = Regex::new(&format!("^{}$", regex::escape(name))) {
 95→                matcher.add_pattern(SecretPattern {
 96→                    name: format!("custom:{}", name),
 97→                    env_pattern: pattern,
 98→                });
 99→            }
100→        }

  1→//! Failure telemetry: scrubbing, consent, and local report storage.
  2→//!
  3→//! After a successful recovery (step eventually passes after retry, fix,
  4→//! or shell), optionally prompts the user to share a scrubbed failure report.
  5→//! Reports are stored locally as YAML files under `~/.bivvy/failure-reports/`.
  6→
  7→use std::collections::HashMap;
  8→use std::fmt;
  9→use std::path::{Path, PathBuf};
 10→use std::sync::LazyLock;
 11→
 12→use regex::Regex;
 13→use serde::{Deserialize, Serialize};
 14→
 15→use crate::error::Result;
 16→use crate::secrets::mask::OutputMasker;
 17→use crate::secrets::pattern::SecretMatcher;
 18→use crate::ui::{Prompt, PromptOption, PromptType, UserInterface};
 19→
 20→/// Regex for scrubbing filesystem paths.
 21→static PATH_REGEX: LazyLock<Regex> = LazyLock::new(|| {
 22→    Regex::new(r"(?:/Users/[^\s:]+|/home/[^\s:]+|/tmp/[^\s:]+|C:\\Users\\[^\s:]+)")
 23→        .expect("PATH_REGEX must compile")
 24→});
 25→
 26→/// Regex for scrubbing token-like strings (hex > 16 chars, base64 blobs, known prefixes).
 27→static TOKEN_REGEX: LazyLock<Regex> = LazyLock::new(|| {
 28→    Regex::new(r"(?:ghp_[A-Za-z0-9]{36,}|gho_[A-Za-z0-9]{36,}|sk-[A-Za-z0-9]{20,}|xoxb-[A-Za-z0-9\-]+|xoxp-[A-Za-z0-9\-]+|[A-Fa-f0-9]{32,}|[A-Za-z0-9+/]{40,}={0,2})")
 29→        .expect("TOKEN_REGEX must compile")
 30→});
 31→
 32→/// Maximum length of scrubbed error output in a report.
 33→const MAX_ERROR_LENGTH: usize = 500;
 34→
 35→/// User's telemetry consent preference.
 36→#[derive(Debug, Clone, PartialEq, Eq)]
 37→pub enum TelemetryConsent {
 38→    /// Send this one report.
 39→    Send,
 40→    /// Don't send this report.
 41→    NoThanks,
 42→    /// Always send (save preference).
 43→    Always,
 44→    /// Never ask again (save preference).
 45→    Never,
 46→}
 47→
 48→impl fmt::Display for TelemetryConsent {
 49→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 50→        match self {
 51→            TelemetryConsent::Send => write!(f, "send"),
 52→            TelemetryConsent::NoThanks => write!(f, "no_thanks"),
 53→            TelemetryConsent::Always => write!(f, "always"),
 54→            TelemetryConsent::Never => write!(f, "never"),
 55→        }
 56→    }
 57→}
 58→
 59→/// A scrubbed failure report.
 60→#[derive(Debug, Clone, Serialize, Deserialize)]
 61→pub struct FailureReport {
 62→    /// Step name (e.g., "bundler").
 63→    pub step_name: String,
 64→    /// Scrubbed command (e.g., "bundle install").
 65→    pub command_scrubbed: String,
 66→    /// Process exit code.
 67→    pub exit_code: Option<i32>,
 68→    /// Scrubbed error output (first 500 chars).
 69→    pub error_scrubbed: String,
 70→    /// Recovery action taken (e.g., "retry", "shell → retry").
 71→    pub recovery_action: String,
 72→    /// Bivvy version.
 73→    pub bivvy_version: String,
 74→    /// Platform string (e.g., "macos-aarch64").
 75→    pub platform: String,
 76→}
 77→
 78→/// Scrub sensitive data from text for telemetry.
 79→///
 80→/// 1. Masks known secret env var values using `OutputMasker`
 81→/// 2. Replaces filesystem paths with `[PATH]`
 82→/// 3. Replaces token-like strings with `[REDACTED]`
 83→/// 4. Truncates to `MAX_ERROR_LENGTH` chars
 84→pub fn scrub_for_telemetry(input: &str, step_env: &HashMap<String, String>) -> String {
 85→    let matcher = SecretMatcher::with_builtins();
 86→    let mut masker = OutputMasker::new();
 87→
 88→    // Mask known secret env var values
 89→    for (key, value) in step_env {
 90→        if matcher.is_secret(key) && !value.is_empty() {
 91→            masker.add_secret(value);
 92→        }
 93→    }
 94→
 95→    let mut result = masker.mask(input);
 96→
 97→    // Scrub filesystem paths
 98→    result = PATH_REGEX.replace_all(&result, "[PATH]").to_string();
 99→
100→    // Scrub token-like strings
101→    result = TOKEN_REGEX.replace_all(&result, "[REDACTED]").to_string();
102→
103→    // Truncate
104→    if result.len() > MAX_ERROR_LENGTH {
105→        result.truncate(MAX_ERROR_LENGTH);
106→        result.push_str("...[truncated]");
107→    }
108→
109→    result
110→}
111→
112→/// Build a `FailureReport` from step failure context.
113→pub fn build_report(
114→    step_name: &str,
115→    command: &str,
116→    exit_code: Option<i32>,
117→    error_output: &str,
118→    recovery_action: &str,
119→    step_env: &HashMap<String, String>,
120→) -> FailureReport {
121→    let platform = format!("{}-{}", std::env::consts::OS, std::env::consts::ARCH);
122→
123→    FailureReport {
124→        step_name: step_name.to_string(),
125→        command_scrubbed: scrub_for_telemetry(command, step_env),
126→        exit_code,
127→        error_scrubbed: scrub_for_telemetry(error_output, step_env),
128→        recovery_action: recovery_action.to_string(),
129→        bivvy_version: env!("CARGO_PKG_VERSION").to_string(),
130→        platform,
131→    }
132→}
133→
134→/// Prompt the user for telemetry consent after a successful recovery.
135→///
136→/// Returns `None` if the preference is already saved (always/never).
137→/// Checks `preferences_other` for the `telemetry_failures` key.
138→pub fn prompt_telemetry(
139→    ui: &mut dyn UserInterface,
140→    report: &FailureReport,
141→    saved_preference: Option<&str>,
142→) -> Result<TelemetryConsent> {
143→    // Check saved preference
144→    match saved_preference {
145→        Some("always") => return Ok(TelemetryConsent::Always),
146→        Some("never") => return Ok(TelemetryConsent::Never),
147→        _ => {}
148→    }
149→
150→    // Show the scrubbed report to the user
151→    ui.message("");
152→    ui.message("  Help bivvy get smarter?");
153→    ui.message("  We'd save this failure report to improve auto-recovery:");
154→    ui.message("");
155→    ui.message(&format!("    Step:    {}", report.step_name));
156→    ui.message(&format!("    Command: {}", report.command_scrubbed));
157→    if let Some(code) = report.exit_code {
158→        ui.message(&format!("    Exit:    {}", code));
159→    }
160→    if !report.error_scrubbed.is_empty() {
161→        ui.message(&format!("    Error:   {}", report.error_scrubbed));
162→    }
163→    ui.message(&format!("    Fix:     {}", report.recovery_action));
164→    ui.message("");
165→    ui.message("    NO env vars, paths, secrets, or project code — just the above.");
166→    ui.message("");
167→
168→    let prompt = Prompt {
169→        key: "telemetry_failure".to_string(),
170→        question: "Save this failure report?".to_string(),
171→        prompt_type: PromptType::Select {
172→            options: vec![
173→                PromptOption {
174→                    label: "Send".to_string(),
175→                    value: "send".to_string(),
176→                },
177→                PromptOption {
178→                    label: "No thanks".to_string(),
179→                    value: "no_thanks".to_string(),
180→                },
181→                PromptOption {
182→                    label: "Always send".to_string(),
183→                    value: "always".to_string(),
184→                },
185→                PromptOption {
186→                    label: "Never ask".to_string(),
187→                    value: "never".to_string(),
188→                },
189→            ],
190→        },
191→        default: Some("no_thanks".to_string()),
192→    };
193→
194→    let answer = ui.prompt(&prompt)?;
195→    match answer.as_string().as_str() {
196→        "send" => Ok(TelemetryConsent::Send),
197→        "always" => Ok(TelemetryConsent::Always),
198→        "never" => Ok(TelemetryConsent::Never),
199→        _ => Ok(TelemetryConsent::NoThanks),
200→    }
201→}
202→
203→/// Get the failure reports directory path.
204→pub fn reports_dir() -> PathBuf {
205→    dirs::home_dir()
206→        .unwrap_or_else(|| PathBuf::from("~"))
207→        .join(".bivvy")
208→        .join("failure-reports")
209→}
210→
211→/// Save a failure report to disk.
212→///
213→/// Reports are saved as timestamped YAML files in `~/.bivvy/failure-reports/`.
214→pub fn save_report(report: &FailureReport) -> Result<PathBuf> {
215→    save_report_to(report, &reports_dir())
216→}
217→
218→/// Save a failure report to a specific directory (for testing).
219→pub fn save_report_to(report: &FailureReport, dir: &Path) -> Result<PathBuf> {
220→    std::fs::create_dir_all(dir)?;
221→
222→    let timestamp = chrono::Utc::now().format("%Y%m%d-%H%M%S");
223→    let filename = format!("{}-{}.yml", timestamp, report.step_name);
224→    let path = dir.join(filename);
225→
226→    let content = serde_yaml::to_string(report).map_err(|e| {
227→        crate::error::BivvyError::ConfigValidationError {
228→            message: format!("Failed to serialize failure report: {}", e),
229→        }
230→    })?;
231→
232→    std::fs::write(&path, content)?;
233→    Ok(path)
234→}
