        ui.set_prompt_response("telemetry_failure", "send");

        prompt_telemetry(&mut ui, &report, Some("unknown_value")).unwrap();
        assert!(
            !ui.prompts_shown().is_empty(),
            "Unknown preference should still show prompt"
        );
    }
}

